import re
from datetime import date

_MONTH_NAMES = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
_MONTHS = {}
for _i, _name in enumerate(_MONTH_NAMES, start=1):
    _MONTHS[_name] = _i
    _MONTHS[_name[:3]] = _i
_MONTHS["sept"] = 9

_WEEKDAYS = {
    "monday", "mon",
    "tuesday", "tue", "tues",
    "wednesday", "wed", "weds",
    "thursday", "thu", "thur", "thurs",
    "friday", "fri",
    "saturday", "sat",
    "sunday", "sun",
}


def _build(y: int, m: int, d: int) -> str:
    """Return ISO date string if (y, m, d) is a real calendar date, else 'INVALID'."""
    try:
        return date(y, m, d).isoformat()
    except ValueError:
        return "INVALID"


def _month_from_token(tok: str):
    t = tok.lower().rstrip(".")
    return _MONTHS.get(t)


def _is_weekday_token(tok: str) -> bool:
    return tok.lower().rstrip(".") in _WEEKDAYS


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    s = re.sub(r"\s+", " ", s.strip())
    if not s:
        return "INVALID"

    # Strip ordinal suffixes (1st, 2nd, 3rd, 4th, ...) after day numbers.
    s = re.sub(r"\b(\d{1,2})(st|nd|rd|th)\b", r"\1", s, flags=re.IGNORECASE)
    # Commas are optional separators in textual dates ("Nov 31, 2022").
    s = s.replace(",", " ")
    s = re.sub(r"\s+", " ", s).strip()

    # Drop weekday names ("Tuesday March 5 2024"); they carry no date information.
    tokens = [t for t in s.split(" ") if t and not _is_weekday_token(t)]
    if not tokens:
        return "INVALID"
    s = " ".join(tokens)

    # ISO-like: YYYY-MM-DD (also allow YYYY/MM/DD and YYYY.MM.DD).
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", s)
    if m:
        return _build(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Textual: "D Mon YYYY" or "Mon D YYYY".
    if len(tokens) == 3:
        a, b, c = tokens
        if re.fullmatch(r"\d{4}", c):
            if re.fullmatch(r"\d{1,2}", a) and _month_from_token(b):
                return _build(int(c), _month_from_token(b), int(a))
            if _month_from_token(a) and re.fullmatch(r"\d{1,2}", b):
                return _build(int(c), _month_from_token(a), int(b))

    # Numeric with separators: either Y-M-D or a day/month-first form with a 4-digit year.
    m = re.fullmatch(r"(\d{1,4})[/.\-](\d{1,2})[/.\-](\d{1,4})", s)
    if m:
        p1, p2, p3 = m.group(1), m.group(2), m.group(3)
        if len(p1) == 4 and len(p3) <= 2:
            return _build(int(p1), int(p2), int(p3))
        if len(p3) == 4 and len(p1) <= 2:
            a, b, y = int(p1), int(p2), int(p3)
            if a > 12 and b <= 12:
                return _build(y, b, a)          # day > 12 => day first
            if b > 12 and a <= 12:
                return _build(y, a, b)          # second part > 12 => month first
            if a <= 12 and b <= 12:
                return _build(y, b, a)          # ambiguous: assumed day-first (unverified)
        return "INVALID"

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)(?:day)?\.?,?\s+",
    re.IGNORECASE,
)
_ORDINAL = r"(?:st|nd|rd|th)?"
_SEP = r"[\s\-/.]+"


def _to_iso(year: int, month: int, day: int) -> str:
    """Return ISO date string, or 'INVALID' if the calendar date does not exist."""
    try:
        return date(year, month, day).isoformat()
    except (ValueError, TypeError):
        return "INVALID"


def _month_number(name: str):
    key = name.strip().rstrip(".").lower()
    return _MONTHS.get(key)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = re.sub(r"\s+", " ", s).strip().rstrip(",").strip()
    if not text:
        return "INVALID"

    # Drop an optional leading weekday name, e.g. "Tuesday, 22 Feb 1900".
    text = _WEEKDAY_PREFIX.sub("", text).strip()
    lowered = text.lower()

    # ISO-like: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", lowered)
    if m:
        y, mo, d = map(int, m.groups())
        return _to_iso(y, mo, d)

    # Numeric with 4-digit year: DD/MM/YYYY or MM/DD/YYYY.
    # Unambiguous when one part exceeds 12; otherwise day-first is assumed.
    m = re.fullmatch(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})", lowered)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if a > 12:
            day, mo = a, b
        elif b > 12:
            mo, day = a, b
        else:
            day, mo = a, b
        return _to_iso(y, mo, day)

    # Day Month Year: "22nd Feb 1900", "22 February, 1900", "22-Feb-1900"
    m = re.fullmatch(
        r"(\d{1,2})" + _ORDINAL + _SEP + r"([a-z]+\.?),?" + _SEP + r"(\d{4})",
        lowered,
    )
    if m:
        d = int(m.group(1))
        mo = _month_number(m.group(2))
        if mo is None:
            return "INVALID"
        return _to_iso(int(m.group(3)), mo, d)

    # Month Day Year: "Feb 22nd 1900", "Nov 31, 2022", "February 22, 1900"
    m = re.fullmatch(
        r"([a-z]+\.?)" + _SEP + r"(\d{1,2})" + _ORDINAL + r",?" + _SEP + r"(\d{4})",
        lowered,
    )
    if m:
        mo = _month_number(m.group(1))
        if mo is None:
            return "INVALID"
        return _to_iso(int(m.group(3)), mo, int(m.group(2)))

    return "INVALID"
